    'every_api_key_the_people_in_this_organizatio_15e73625' => 'Varje API-nyckel som personerna i den här organisationen har skapat för sina appar. Återkalla en som läckt eller inte längre används. Människor skapar sina egna nycklar under Mitt konto.',
